  let a=start+cell.y*width;
  let b=start+next.y*width;
  let rock=mix(
    mix(studio_region_cell(a+cell.x),studio_region_cell(a+next.x),t.x),
    mix(studio_region_cell(b+cell.x),studio_region_cell(b+next.x),t.x),t.y);
